package com.ruoyi.paiflow.service;

import com.alibaba.fastjson2.*;
import java.nio.charset.StandardCharsets;
import java.net.URI;
import java.util.*;
import static com.ruoyi.paiflow.service.ModelOperationJson.error;

/** 原Link四位置、x-from、默认值及Python JSON编码；Schema不授予网络或写许可。 */
final class ToolSchema {
 private ToolSchema() {}
 static void budgetApi(JSONObject api){record Entry(Object value,int depth){}var stack=new ArrayDeque<Entry>();stack.add(new Entry(api,0));int nodes=0;while(!stack.isEmpty()){var next=stack.remove();if(next.depth()>64||++nodes>100000)throw error("工具OpenAPI结构超过预算",413);if(next.value() instanceof JSONObject o)for(Object v:o.values())if(v!=null)stack.add(new Entry(v,next.depth()+1));if(next.value() instanceof JSONArray a)for(Object v:a)if(v!=null)stack.add(new Entry(v,next.depth()+1));}if(api.toJSONString(JSONWriter.Feature.WriteMapNullValue).getBytes(StandardCharsets.UTF_8).length>1024*1024)throw error("工具OpenAPI超过1MiB预算",413);}
 record Operation(String path,String method,JSONObject schema) {}
 static Map<String,Operation> operations(JSONObject api){
  if(api==null || !(api.get("paths") instanceof JSONObject paths) || paths.isEmpty())throw error("工具OpenAPI缺少paths",422);
  var result=new LinkedHashMap<String,Operation>();
  for(var p:paths.entrySet()){if(!p.getKey().startsWith("/") || !(p.getValue() instanceof JSONObject rawMethods))throw error("工具路径无效",422);
   var methods=ToolJsonSchema.dereference(api,rawMethods);for(var m:methods.entrySet()){if(!ToolOpenApi.METHODS.contains(m.getKey()))continue;
    if(!(m.getValue() instanceof JSONObject rawOp))throw error("工具operation形状无效",422);var op=ToolOpenApi.operation(api,methods,rawOp);String id=text(op.get("operationId"),128,"operationId");
    if(result.put(id,new Operation(p.getKey(),m.getKey().toUpperCase(Locale.ROOT),op))!=null)throw error("工具operationId重复",422);
    var parameters=op.getJSONArray("parameters");if(parameters!=null){var used=new HashSet<String>();for(Object raw:parameters){if(!(raw instanceof JSONObject item)|| item.getString("in")==null||!Set.of("header","query","path").contains(item.getString("in")) || !used.add(item.getString("in")+":"+text(item.get("name"),128,"参数名")) || !(item.get("schema") instanceof JSONObject schema))throw error("工具参数位置或名称无效",422);ToolJsonSchema.check(schema,api);}}
    if(op.get("requestBody") instanceof JSONObject body){var content=body.getJSONObject("content");if(content==null || !content.keySet().equals(Set.of("application/json")))throw error("原Link仅支持application/json请求体",422);ToolJsonSchema.check(content.getJSONObject("application/json").getJSONObject("schema"),api);}
    var responses=op.getJSONObject("responses");if(responses==null || !(responses.get("200") instanceof JSONObject success) || success.getJSONObject("content")==null || success.getJSONObject("content").getJSONObject("application/json")==null)throw error("工具缺少原200 JSON响应schema",422);
    ToolJsonSchema.check(success.getJSONObject("content").getJSONObject("application/json").getJSONObject("schema"),api);
  }}return result;
 }
 static void check(JSONObject s,int depth){ToolJsonSchema.check(s,null);}
 static void validate(Object value,JSONObject s,String path){ToolJsonSchema.validate(value,s,null,path);}
 static JSONObject expected(JSONObject execution,JSONObject node,JSONObject input,JSONArray events,JSONObject descriptor){
  return expected(node,WorkflowInputSources.values(execution,node,input,events),descriptor);
 }
 static JSONObject expected(JSONObject node,Map<String,Object> verifiedInputs,JSONObject descriptor){
  var p=node.getJSONObject("data").getJSONObject("nodeParam");var op=operations(descriptor.getJSONObject("openApiSchema")).get(p.getString("operationId"));if(op==null)throw error("工具固定operation不存在",409);
  var action=new JSONObject(verifiedInputs);var business=new JSONObject();var names=p.getJSONArray("businessInput");if(names!=null)for(Object name:names){var queue=new ArrayDeque<Object>();queue.add(action);while(!queue.isEmpty()){Object item=queue.remove();if(item instanceof JSONObject o){for(var entry:o.entrySet()){if(entry.getKey().equals(name)){business.put(name.toString(),entry.getValue());break;}if(entry.getValue() instanceof JSONObject||entry.getValue() instanceof JSONArray)queue.add(entry.getValue());}}else if(item instanceof JSONArray a)for(Object v:a)if(v instanceof JSONObject||v instanceof JSONArray)queue.add(v);}}
  var positions=JSONObject.of("header",new JSONObject(),"query",new JSONObject(),"path",new JSONObject());var parameters=op.schema().getJSONArray("parameters");if(parameters!=null)for(Object raw:parameters){var item=(JSONObject)raw;var schema=item.getJSONObject("schema");String name=item.getString("name");var source=schema.getIntValue("x-from",0)==1?business:action;Object value=source.containsKey(name)?source.get(name):schema.get("default");positions.getJSONObject(item.getString("in")).put(name,value);if(Boolean.TRUE.equals(item.get("required"))||value!=null)ToolJsonSchema.validate(value,schema,descriptor.getJSONObject("openApiSchema"),item.getString("in")+"/"+name);}
  var request=op.schema().getJSONObject("requestBody");if(request!=null){var bodySchema=request.getJSONObject("content").getJSONObject("application/json").getJSONObject("schema");var assembled=body(bodySchema,action,business);ToolJsonSchema.validate(assembled,bodySchema,descriptor.getJSONObject("openApiSchema"),"body");positions.put("body",assembled);}
  var message=new JSONObject();for(var field:positions.entrySet())if(field.getValue() instanceof JSONObject value&&!value.isEmpty()){RunJsonBoundary.check(value,2*1024*1024);message.put(field.getKey(),Base64.getEncoder().encodeToString(pythonJson(value).getBytes(StandardCharsets.UTF_8)));}
  return JSONObject.of("header",JSONObject.of("app_id",p.get("appId")),"parameter",JSONObject.of("tool_id",p.get("pluginId"),"operation_id",p.get("operationId"),"version",p.getOrDefault("version","V1.0")),"payload",JSONObject.of("message",message));
 }
 private static JSONObject body(JSONObject schema,JSONObject action,JSONObject business){var result=new JSONObject();var props=schema.getJSONObject("properties");if(props==null)return result;for(var f:props.entrySet()){var s=(JSONObject)f.getValue();String name=f.getKey();if("object".equals(s.get("type"))){Object nested=action.getOrDefault(name,new JSONObject());if(!(nested instanceof JSONObject child))throw error("工具嵌套object输入无效",422);result.put(name,body(s,child,business));}else{Object value=(s.getIntValue("x-from",0)==1?business:action).get(name);if(value==null)value=s.get("default");if(value!=null)result.put(name,value);}}return result;}
 static void comparePayload(JSONObject actual,JSONObject expected){
  RunJsonBoundary.fields(actual,Set.of("header","parameter","payload"),Set.of());if(!same(actual.get("header"),expected.get("header"))||!same(actual.get("parameter"),expected.get("parameter")))throw error("Worker工具声明与固定节点不一致",409);
  var payload=actual.getJSONObject("payload");RunJsonBoundary.fields(payload,Set.of("message"),Set.of());var message=payload.getJSONObject("message");var wanted=expected.getJSONObject("payload").getJSONObject("message");if(message==null||!message.keySet().equals(wanted.keySet()))throw error("Worker工具参数位置改变",409);
  for(String key:message.keySet()){Object decoded=decode(message.get(key)),fixed=decode(wanted.get(key));RunJsonBoundary.check(decoded,2*1024*1024);if(!same(decoded,fixed))throw error("Worker工具参数偏离真实中心输入："+key,409);}
 }
 static JSONObject decode(Object value){try{if(!(value instanceof String s)||s.length()>2800000)throw new IllegalArgumentException();byte[] bytes=Base64.getDecoder().decode(s);String decoded=StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(bytes)).toString();var factory=com.fasterxml.jackson.core.JsonFactory.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).build();try(var parser=factory.createParser(decoded)){var mapper=new com.fasterxml.jackson.databind.ObjectMapper(factory);var json=mapper.readTree(parser);if(json==null||!json.isObject()||parser.nextToken()!=null)throw new IllegalArgumentException();}var result=JSON.parseObject(decoded);RunJsonBoundary.check(result,2*1024*1024);return result;}catch(java.io.IOException|RuntimeException e){throw error("工具base64 JSON参数无效",400);}}
 static boolean same(Object a,Object b){return Objects.equals(json(a),json(b));}
 static String json(Object v){return RunJsonBoundary.canonicalFull(JSONObject.of("v",v));}
 static String text(Object raw,int max,String name){if(!(raw instanceof String s)||s.isBlank()||s.codePointCount(0,s.length())>max)throw error(name+"无效",400);return s;}
 static String pythonJson(Object v){if(v instanceof Map<?,?> map){var parts=new ArrayList<String>();map.forEach((k,x)->parts.add(ascii(JSON.toJSONString(k))+": "+pythonJson(x)));return "{"+String.join(", ",parts)+"}";}if(v instanceof List<?> list)return "["+String.join(", ",list.stream().map(ToolSchema::pythonJson).toList())+"]";return ascii(ModelMessageSources.pythonJson(v));}
 private static String ascii(String text){var out=new StringBuilder();for(char c:text.toCharArray())if(c>127)out.append(String.format("\\u%04x",(int)c));else out.append(c);return out.toString();}
 static JSONObject publicApi(JSONObject api){return ToolOpenApi.publicApi(api);}
 static void guardApi(JSONObject api){
  var copy=ToolOpenApi.copy(api);var paths=copy.getJSONObject("paths");if(paths!=null)for(Object raw:paths.values()){if(!(raw instanceof JSONObject path))throw error("工具path形状无效",422);guardParameters(path.getJSONArray("parameters"));for(var field:path.entrySet())if(ToolOpenApi.METHODS.contains(field.getKey())){if(!(field.getValue() instanceof JSONObject op))throw error("工具operation形状无效",422);guardOperation(op);}}
  guardSecurity(copy);var components=copy.getJSONObject("components");if(components!=null){if(components.get("schemas") instanceof JSONObject schemas){for(Object s:schemas.values())RunJsonBoundary.checkSchema(s,1024*1024);components.remove("schemas");}if(components.get("parameters") instanceof JSONObject parameters)for(Object p:parameters.values())guardParameter((JSONObject)p);if(components.get("requestBodies") instanceof JSONObject bodies)for(Object b:bodies.values())guardContent(((JSONObject)b).getJSONObject("content"));if(components.get("responses") instanceof JSONObject responses)for(Object r:responses.values())guardContent(((JSONObject)r).getJSONObject("content"));if(components.get("securitySchemes") instanceof JSONObject schemes){for(Object raw:schemes.values()){if(!(raw instanceof JSONObject s)||!s.keySet().stream().allMatch(k->Set.of("type","in","name","description").contains(k))||!"apiKey".equals(s.get("type"))||s.getString("in")==null||!Set.of("header","query").contains(s.getString("in")))throw error("工具认证方案尚未接通或含私有注解",422);}components.remove("securitySchemes");}}RunJsonBoundary.check(copy,1024*1024);
 }
 private static void guardParameter(JSONObject parameter){if(parameter.containsKey("schema"))RunJsonBoundary.checkSchema(parameter.remove("schema"),1024*1024);}
 private static void guardParameters(JSONArray parameters){if(parameters!=null)for(Object p:parameters){if(!(p instanceof JSONObject item))throw error("工具参数形状无效",422);guardParameter(item);}}
 private static void guardContent(JSONObject content){if(content!=null)for(Object raw:content.values()){if(!(raw instanceof JSONObject media))throw error("工具content形状无效",422);if(media.containsKey("schema"))RunJsonBoundary.checkSchema(media.remove("schema"),1024*1024);}}
 private static void guardOperation(JSONObject op){guardParameters(op.getJSONArray("parameters"));if(op.get("requestBody") instanceof JSONObject body)guardContent(body.getJSONObject("content"));if(op.get("responses") instanceof JSONObject responses)for(Object r:responses.values())guardContent(((JSONObject)r).getJSONObject("content"));guardSecurity(op);}
 private static void guardSecurity(JSONObject op){if(op.containsKey("security")){var security=op.getJSONArray("security");if(security==null)throw error("工具security定义无效",422);for(Object requirement:security){if(!(requirement instanceof JSONObject requirements))throw error("工具security定义无效",422);for(Object scopes:requirements.values())if(!(scopes instanceof JSONArray array)||array.stream().anyMatch(v->!(v instanceof String)))throw error("工具security定义无效",422);}op.remove("security");}}
 static JSONObject fromWeb(JSONObject form){
  var web=form.get("webSchema") instanceof String s?JSON.parseObject(s):form.getJSONObject("webSchema");if(web==null)throw error("工具缺少OpenAPI或webSchema",422);
  var parameters=new JSONArray();var bodyInputs=new JSONArray();var inputs=web.getJSONArray("toolRequestInput");if(inputs!=null)for(Object raw:inputs){var item=(JSONObject)raw;String location=item.getString("location");if("body".equals(location))bodyInputs.add(item);else if(location!=null&&Set.of("header","query","path").contains(location))parameters.add(JSONObject.of("in",location,"name",item.get("name"),"required",item.getOrDefault("required",false),"schema",webField(item)));else throw error("原工具参数位置无效",422);}
  URI endpoint=URI.create(text(form.get("endPoint"),2048,"endPoint"));String path=endpoint.getRawPath();if(path==null||path.isEmpty())path="/";var op=JSONObject.of("operationId",form.getOrDefault("operationId",form.get("name")),"parameters",parameters,"responses",JSONObject.of("200",JSONObject.of("content",JSONObject.of("application/json",JSONObject.of("schema",webObject(web.getJSONArray("toolRequestOutput")))))));
  if(!bodyInputs.isEmpty())op.put("requestBody",JSONObject.of("content",JSONObject.of("application/json",JSONObject.of("schema",webObject(bodyInputs)))));
  return JSONObject.of("openapi","3.0.0","info",JSONObject.of("title",form.get("name"),"version","1.0.0"),"servers",new JSONArray(List.of(JSONObject.of("url",endpoint.getScheme()+"://"+endpoint.getRawAuthority()))),"paths",JSONObject.of(path,JSONObject.of(text(form.get("method"),16,"method").toLowerCase(Locale.ROOT),op)));
 }
 private static JSONObject webObject(JSONArray fields){var p=new JSONObject();var required=new JSONArray();if(fields!=null)for(Object raw:fields){var f=(JSONObject)raw;String name=text(f.get("name"),128,"字段名");if(p.put(name,webField(f))!=null)throw error("原工具字段重名",422);if(Boolean.TRUE.equals(f.get("required")))required.add(name);}return JSONObject.of("type","object","properties",p,"required",required);}
 private static JSONObject webField(JSONObject f){String type=f.getString("type");var s=JSONObject.of("type",type,"description",f.getOrDefault("description",""));if(f.containsKey("from"))s.put("x-from",f.get("from"));if(f.containsKey("dft")||f.containsKey("default")){Object value=f.containsKey("dft")?f.get("dft"):f.get("default");if(value instanceof String text&&!"string".equals(type)&&!text.isEmpty())try{value=JSON.parse(text);}catch(RuntimeException e){throw error("原工具默认值不是声明类型",422);}s.put("default",value);}if("object".equals(type))s.putAll(webObject(f.getJSONArray("children")));if("array".equals(type)){var children=f.getJSONArray("children");if(children==null||children.size()!=1)throw error("原工具数组items定义尚未接通",422);s.put("items",webField(children.getJSONObject(0)));}return s;}
}
